@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  /* ──────────────────────────────────────────────────────────
     INKOS BRAND SWATCHES — Brand Book v1.0 (LOCKED)
     Bone · Onyx · Stone · Rust — no additions, no substitutes
  ────────────────────────────────────────────────────────── */
  --color-bone: #F7F7F5;
  --color-onyx: #0F0F0F;
  --color-stone: #787774;
  --color-rust: #B23A2B;

  --font-sans: var(--font-sans), 'Inter', -apple-system, sans-serif;
  --font-serif: var(--font-serif), 'Instrument Serif', Georgia, serif;
  --font-mono: var(--font-mono), 'JetBrains Mono', monospace;

  /* ──────────────────────────────────────────────────────────
     SEMANTIC PALETTE — derived from brand swatches
     Rule: never pure #FFF or #000. Bone/Onyx only.
  ────────────────────────────────────────────────────────── */

  /* Bone — 60% usage. Page canvas + sidebar bg. */
  --color-background: #F7F7F5;

  /* Onyx — 20% usage. Primary text + CTAs. */
  --color-foreground: #0F0F0F;

  /* Card surface — pure white on Bone, so cards "float" */
  --color-card: #FFFFFF;
  --color-card-foreground: #0F0F0F;

  --color-popover: #FFFFFF;
  --color-popover-foreground: #0F0F0F;

  /* Primary = Onyx (NOT Rust). Primary CTAs are black. */
  --color-primary: #0F0F0F;
  --color-primary-foreground: #F7F7F5;

  /* Secondary — muted Bone tint */
  --color-secondary: oklch(96% 0.003 60);
  --color-secondary-foreground: #0F0F0F;

  /* Muted — Stone-tinted backgrounds */
  --color-muted: oklch(95% 0.003 60);
  --color-muted-foreground: #787774;

  /* Accent — Rust at 12% opacity for active nav states */
  --color-accent: rgba(178, 58, 43, 0.08);
  --color-accent-foreground: #B23A2B;

  /* Destructive = Rust. Reserved for LIVE pill, active nav, destructive only. */
  --color-destructive: #B23A2B;
  --color-destructive-foreground: #F7F7F5;

  /* ──────────────────────────────────────────────────────────
     SEMANTIC STATUS TOKENS
  ────────────────────────────────────────────────────────── */
  --color-success:            oklch(58% 0.18 145);
  --color-success-bg:         oklch(94% 0.05 145);
  --color-success-foreground: oklch(26% 0.12 145);
  --color-warning:            oklch(70% 0.16 72);
  --color-warning-bg:         oklch(94% 0.07 72);
  --color-warning-foreground: oklch(36% 0.15 72);

  /* Borders — Stone-tinted, visible but light */
  --color-border: oklch(89% 0.002 60);
  --color-input: oklch(89% 0.002 60);
  --color-ring: #0F0F0F;

  /* ──────────────────────────────────────────────────────────
     SHADOWS — custom (never use Tailwind default shadow-sm/md)
  ────────────────────────────────────────────────────────── */

  /* Soft border shadow for cards on white — bumped alpha so cards read on bone bg */
  --shadow-soft: 0 1px 2px 0 oklch(20% 0.02 85 / 0.08), 0 1px 3px 0 oklch(20% 0.02 85 / 0.05);

  /* Standard card elevation — visible on off-white page */
  --shadow-card: 0 1px 3px 0 oklch(20% 0.02 85 / 0.10), 0 2px 4px -1px oklch(20% 0.02 85 / 0.06);

  /* Hover elevation */
  --shadow-card-hover: 0 6px 16px -4px oklch(20% 0.02 85 / 0.14), 0 3px 8px -2px oklch(20% 0.02 85 / 0.09);

  /* Medium depth for drawers, modals */
  --shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 85 / 0.10), 0 2px 8px -2px oklch(13% 0.015 85 / 0.07);

  /* Floating elements — command palette, toasts, tooltips */
  --shadow-lift: 0 8px 24px -4px oklch(13% 0.015 85 / 0.14),
                 0 4px 10px -2px oklch(13% 0.015 85 / 0.08);

  /* Full-screen overlays — modal backdrop shadow on dialog */
  --shadow-overlay: 0 24px 64px -12px oklch(13% 0.015 85 / 0.22),
                    0 8px 24px -4px oklch(13% 0.015 85 / 0.12);

  /* ──────────────────────────────────────────────────────────
     RADIUS
  ────────────────────────────────────────────────────────── */

'use client'

import { useMemo } from 'react'
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
} from '@/components/ui/sidebar'
import { SidebarNavGroup } from '@/components/app/sidebar/SidebarNavGroup'
import type { DynamicBadgeCounts } from '@/components/app/sidebar/SidebarNavGroup'
import { APP_NAV, type NavRole } from '@/components/app/sidebar/nav-config'
import { BookingLinkWidget } from '@/components/app/sidebar/BookingLinkWidget'
import { SidebarFavorites } from '@/components/app/sidebar/SidebarFavorites'
import { SidebarUserFooter } from '@/components/app/sidebar/SidebarUserFooter'
import { StudioSwitcher } from '@/components/shared/StudioSwitcher'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { StudioMembership } from '@/lib/context/active-studio'
import type { UserPinnedItem } from '@/lib/pinned-items/pinned'

interface AppSidebarProps {
  plan: PlanTier
  studioName: string
  studioLogoUrl?: string | null
  studioSlug: string
  role: NavRole
  locationCount: number
  /** Serialized from server — Set<string> → JSON array → passed as prop */
  permissionKeys?: string[]
  /** Dynamic badge counts from server (inbox, calendar, clients, inventory) */
  dynamicBadges?: DynamicBadgeCounts
  /** S15: all studio memberships — single item = no switcher rendered */
  allMemberships: StudioMembership[]
  /** S15: active studio id */
  currentStudioId: string
  /** User info for footer */
  userName: string
  userEmail: string
  userAvatarUrl?: string | null
  /** S22: pinned items for Favorites section */
  pinnedItems?: UserPinnedItem[]
}

export function AppSidebar({
  plan,
  studioName,
  studioLogoUrl,
  studioSlug,
  role,
  locationCount,
  permissionKeys = [],
  dynamicBadges = {},
  allMemberships,
  currentStudioId,
  userName,
  userEmail,
  userAvatarUrl,
  pinnedItems = [],
}: AppSidebarProps) {
  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])

  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
      }))
      .filter((group) => group.items.length > 0)
  }, [role, locationCount, permissions])

  return (
    <Sidebar collapsible="icon" className="border-r border-sidebar-border/60">
      {/* ── Brand header with ⌘K hint ─────────────────────────── */}
      <SidebarHeader className="border-b border-sidebar-border/60 px-3 py-2.5">
        <div className="flex items-center gap-2 group-data-[collapsible=icon]:justify-center">
          {studioLogoUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={studioLogoUrl}
              alt={studioName}
              className="h-8 w-8 shrink-0 rounded-md object-cover"
            />
          ) : (
            /* InkOS brand mark — italic `i` in Onyx tile per brand book */
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-foreground text-background">
              <span className="font-serif-italic text-xl leading-none">i</span>
            </div>
          )}
          <div className="flex min-w-0 flex-col leading-tight group-data-[collapsible=icon]:hidden">
            <span className="truncate text-[13px] font-bold tracking-tight text-sidebar-foreground">
              InkOS
            </span>
            <span className="truncate text-[10px] font-medium uppercase tracking-[0.08em] text-stone-brand">
              {studioName}
            </span>
          </div>
          {/* ⌘K hint pill */}
          <button
            type="button"
            aria-label="Open command palette (⌘K)"
            onClick={() => {
              // Dispatch synthetic ⌘K to trigger AppHeader's palette handler
              window.dispatchEvent(
                new KeyboardEvent('keydown', { key: 'k', metaKey: true, bubbles: true })
              )
            }}
            className="ml-auto flex h-5 shrink-0 items-center gap-0.5 rounded border border-border/50 bg-muted/30 px-1.5 text-[10px] font-mono text-muted-foreground/60 transition-colors hover:border-border hover:bg-muted/60 hover:text-muted-foreground group-data-[collapsible=icon]:hidden"
          >
            <span>⌘</span><span>K</span>
          </button>
        </div>

        {/* Studio switcher row */}
        <div className="mt-2 group-data-[collapsible=icon]:hidden">
          {allMemberships.length >= 2 ? (
            <StudioSwitcher
              currentStudioId={currentStudioId}
              allMemberships={allMemberships}
            />
          ) : (
            <div className="flex h-8 items-center gap-2 rounded-lg border border-border/40 bg-muted/20 px-2">
              <span className="truncate text-[13px] font-medium text-sidebar-foreground/80">
                {studioName}
              </span>
            </div>
          )}
        </div>

        {/* Booking link widget */}
        <BookingLinkWidget studioSlug={studioSlug} className="mt-1.5 mx-0" />
      </SidebarHeader>

      {/* ── Nav groups ────────────────────────────────────────── */}
      <SidebarContent className="gap-0 px-2 py-3">
        {navGroups.map((group, idx) => (
          <SidebarNavGroup
            key={group.label ?? '_unlabeled'}
            group={group}
            plan={plan}
            isFirst={idx === 0}
            dynamicBadges={dynamicBadges}
          />
        ))}

        {/* S22: Favorites */}
        <SidebarFavorites pinnedItems={pinnedItems} />
      </SidebarContent>

      {/* ── User footer ───────────────────────────────────────── */}
      <SidebarFooter className="p-0">
        <SidebarUserFooter
          userName={userName}
          userEmail={userEmail}
          userAvatarUrl={userAvatarUrl}
          role={role}
        />
      </SidebarFooter>
    </Sidebar>
  )
}

'use client'

import { Copy, ExternalLink } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'

interface BookingLinkWidgetProps {
  studioSlug: string
  className?: string
}

/**
 * S17 — Copyable booking link widget shown below the studio switcher.
 * Displays inkos.app/book/{slug} and copies to clipboard on click.
 */
export function BookingLinkWidget({ studioSlug, className }: BookingLinkWidgetProps) {
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'https://inkos.app'
  const bookingUrl = `${appUrl}/book/${studioSlug}`
  const displayUrl = bookingUrl.replace(/^https?:\/\//, '')

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(bookingUrl)
      toast.success('Link copied')
    } catch {
      toast.error('Could not copy link')
    }
  }

  return (
    <div
      className={cn(
        'group/widget mx-2 mb-1 flex items-center gap-1.5 rounded-md border border-border/40 bg-muted/20 px-2 py-1.5 transition-colors hover:border-border/60 hover:bg-muted/40 group-data-[collapsible=icon]:hidden',
        className,
      )}
    >
      <ExternalLink className="h-3 w-3 shrink-0 text-muted-foreground/50" aria-hidden="true" />
      <span
        className="min-w-0 flex-1 truncate text-[11px] text-muted-foreground/70"
        title={displayUrl}
      >
        {displayUrl}
      </span>
      <button
        type="button"
        aria-label="Copy booking link"
        onClick={handleCopy}
        className="flex h-5 w-5 shrink-0 cursor-pointer items-center justify-center rounded opacity-0 transition-all hover:bg-muted/60 group-hover/widget:opacity-100 focus-visible:opacity-100 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
      >
        <Copy className="h-3 w-3 text-muted-foreground/70" aria-hidden="true" />
      </button>
    </div>
  )
}

