import { Copy, Link2, ExternalLink } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'

interface BookingLinkWidgetProps {
  studioSlug: string
  className?: string
}

/**
 * Editorial booking-link chip. Shows "Booking link" label, not the raw URL
 * (truncated URLs break brand rule #1 — editorial polish). Hover reveals
 * Copy + Open actions. Full URL available via title tooltip + aria-label.
 */
export function BookingLinkWidget({ studioSlug, className }: BookingLinkWidgetProps) {
