      <Link2
        className="h-3.5 w-3.5 shrink-0 text-muted-foreground/60"
        aria-hidden="true"
      />
      <span className="min-w-0 flex-1 truncate text-[12px] font-medium text-sidebar-foreground/80">
        Booking link
      </span>
      <div className="flex shrink-0 items-center gap-0.5 opacity-0 transition-opacity group-hover/widget:opacity-100 focus-within:opacity-100">
        <button
          type="button"
          aria-label={`Copy booking link: ${displayUrl}`}
          onClick={handleCopy}
          className="flex h-5 w-5 cursor-pointer items-center justify-center rounded text-muted-foreground/70 transition-colors hover:bg-muted/60 hover:text-sidebar-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
        >
          <Copy className="h-3 w-3" aria-hidden="true" />
        </button>
        <a
          href={bookingUrl}
          target="_blank"
          rel="noopener noreferrer"
          aria-label={`Open booking page: ${displayUrl}`}
          onClick={(e) => e.stopPropagation()}
          className="flex h-5 w-5 cursor-pointer items-center justify-center rounded text-muted-foreground/70 transition-colors hover:bg-muted/60 hover:text-sidebar-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
        >
          <ExternalLink className="h-3 w-3" aria-hidden="true" />
        </a>
      </div>
    </div>
