async function handleSignOut() {
  await supabase.auth.signOut()
  router.push('/login')
  router.refresh()
}

return (
  <SidebarInset className="flex flex-col">
    <header className="relative sticky top-0 z-40 flex h-14 shrink-0 items-center gap-3 border-b border-border/60 bg-[var(--color-header-bg)] px-4 after:pointer-events-none after:absolute after:inset-x-0 after:bottom-0 after:h-px after:bg-[linear-gradient(to_right,_oklch(58%_0.16_35/_0.5),_transparent_55%)]">
      <div className="flex min-w-0 flex-1 items-center gap-2">
        <MobileNav
          userName={userName}
          userEmail={userEmail ?? ''}
          userAvatarUrl={userAvatarUrl}
          studioName={studioName}
          {...(studioSlug !== undefined ? { studioSlug } : {})}
          role={role}
          plan={plan}
          locationCount={allLocations.length}
          permissionKeys={permissionKeys}
          {...(dynamicBadges !== undefined ? { dynamicBadges } : {})}
          onSignOut={handleSignOut}
          open={mobileNavOpen}
          onOpenChange={setMobileNavOpen}
          allMemberships={allMemberships}
          currentStudioId={currentStudioId}
          currentLocationId={currentLocationId}
          allLocations={allLocations}
        />
        <SidebarTrigger className="hidden h-8 w-8 shrink-0 text-muted-foreground/70 hover:text-foreground md:flex" />
        <Separator orientation="vertical" className="h-4 bg-border/50" />

        {/* S18 — Breadcrumb: Dashboard > Section > Page (tab-aware).
            Studio + Location switchers moved to the right side of the header
            as supplementary pills; they are workspace identity, not nav. */}
        <Breadcrumb className="min-w-0">
          <BreadcrumbList className="gap-1.5 text-[13px]">
            {/* Desktop: full trail */}
            {breadcrumbs.map((crumb, i) => {
              const isLast = i === breadcrumbs.length - 1
              return (
                <span key={`${crumb.label}-${i}`} className="hidden items-center gap-1.5 md:flex">
                  {i > 0 && (
                    <BreadcrumbSeparator>
                      <ChevronRight className="h-3.5 w-3.5 text-muted-foreground/40" aria-hidden="true" />
                    </BreadcrumbSeparator>
                  )}
                  <BreadcrumbItem>
                    {isLast || !crumb.href ? (
                      <BreadcrumbPage className="truncate font-semibold tracking-tight text-foreground">
                        {crumb.label}
                      </BreadcrumbPage>
                    ) : (
                      <BreadcrumbLink
                        render={
                          <Link
                            href={crumb.href}
                            className="truncate text-muted-foreground/80 transition-colors hover:text-foreground"
                          />
                        }
                      >
                        {crumb.label}
                      </BreadcrumbLink>
                    )}
                  </BreadcrumbItem>
                </span>
              )
            })}

            {/* Mobile: only the last (current page) crumb to save space */}
            <BreadcrumbItem className="flex md:hidden">
              <BreadcrumbPage className="truncate font-semibold text-foreground">
                {breadcrumbs[breadcrumbs.length - 1]?.label ?? 'Dashboard'}
              </BreadcrumbPage>
            </BreadcrumbItem>
          </BreadcrumbList>
        </Breadcrumb>

        <div aria-live="polite" aria-atomic="true" className="sr-only" id="studio-switch-announcement" />
      </div>

      <div className="flex shrink-0 items-center gap-1.5">
        {/* S18 — Workspace identity pills moved out of breadcrumb and to the
            header-right. Only render when there's something to switch. */}
        {allMemberships.length >= 2 && (
          <div className="hidden md:flex">
            <StudioSwitcher
              currentStudioId={currentStudioId}
              allMemberships={allMemberships}
            />
          </div>
        )}
        {allLocations.length >= 2 && (
          <div className="hidden md:flex">
            <LocationSwitcher
              currentLocationId={currentLocationId}
              allLocations={allLocations}
              role={role as unknown as Parameters<typeof LocationSwitcher>[0]['role']}
            />
          </div>
        )}

        {/* S22: Commission Pulse Pill — desktop only, role-gated */}
        {canViewCommissions && (
          <CommissionPulsePill totalCents={mtdCommissionCents ?? null} />
        )}

        <Button
          variant="ghost"
          className="flex h-11 w-11 items-center justify-center md:hidden"
          aria-label="Search"
          onClick={() => setPaletteOpen(true)}
        >
          <Search className="size-4" aria-hidden="true" />
        </Button>

        <button
          type="button"
          aria-label="Open command palette"
          onClick={() => setPaletteOpen(true)}
          className="hidden h-8 cursor-pointer items-center gap-2 rounded-lg border border-border/60 bg-muted/30 px-2.5 text-[12px] font-medium text-muted-foreground/80 transition-all hover:border-border hover:bg-muted/60 hover:text-foreground md:flex"
        >
          <span>Search</span>
          <kbd className="pointer-events-none flex h-5 items-center gap-0.5 rounded border border-border/60 bg-background px-1.5 text-[10px] font-mono text-muted-foreground/60">
            <span>⌘</span><span>K</span>
          </kbd>
        </button>

        <ThemeToggle variant="icon" />

        <UserMenu
          variant="desktop-header"
          userName={userName}
          userEmail={userEmail ?? ''}
          userAvatarUrl={userAvatarUrl ?? null}
          studioName={studioName}
          role={role}
          canManageWorkspace={role === 'owner' || role === 'admin'}
          onSignOut={handleSignOut}
        />
      </div>
    </header>

    <CommandPalette
      open={paletteOpen}
      onOpenChange={setPaletteOpen}
      onCreateClient={() => setAddClientOpen(true)}
    />
    <QuickAddClientModal open={addClientOpen} onOpenChange={setAddClientOpen} />

    <main
      id="main-content"
      tabIndex={-1}
      className="flex-1 overflow-auto bg-[var(--color-page-bg,var(--color-background))] pb-16 outline-none md:pb-0"
    >
      {children}

import type { NextConfig } from 'next'
import bundleAnalyzer from '@next/bundle-analyzer'

const withBundleAnalyzer = bundleAnalyzer({
  enabled: process.env.ANALYZE === 'true',
})

const nextConfig: NextConfig = {
  output: 'standalone',
  reactStrictMode: true,
  // S19 perf — keep server-only deps out of the client bundle.
  // Prevents accidental client inclusion via transitive imports from lib/.
  serverExternalPackages: ['twilio', 'bullmq', 'ioredis', 'pdf-lib', 'qrcode'],
  experimental: {
    viewTransition: true,
    // S19 perf — Next.js rewrites named imports to subpath imports at build
    // time, dropping unused code from these high-traffic barrel-exporters.
    optimizePackageImports: [
      'date-fns',
      'lucide-react',
      '@tanstack/react-query',
      'sonner',
    ],
  },
  turbopack: {
    root: __dirname,
  },
  outputFileTracingRoot: __dirname,
  images: {
    remotePatterns: [
      {
        protocol: 'https',
        hostname: '*.supabase.co',
      },
    ],
  },
  async redirects() {
    // S13 — Navigation consolidation: old sub-routes → tab params on hub pages.
    // All 307 (temporary) — upgrade to 308 permanent once S14 confirms stability.
    return [
      // S18 — Today → Dashboard (permanent). Flipped from the S17 direction after
      // the sidebar label was renamed to "Dashboard" and the route was promoted.
      { source: '/today', destination: '/dashboard', permanent: true },

      // S17 — Commissions + Payroll → /payments tabs (permanent).
      // No /payroll/:path* wildcard — would break /payroll/runs/[id], /payroll/artist-summaries/[id],
      // /payroll/tax-forms/[id] deep links. Top-level redirects only; nested pages remain reachable
      // via their original URLs (linked from within the Payroll tab).
      { source: '/commissions', destination: '/payments?tab=commissions', permanent: true },
      { source: '/payroll', destination: '/payments?tab=payroll', permanent: true },

      // Appointments
      { source: '/waitlist', destination: '/appointments?tab=waitlist', permanent: false },

      // Artists/Team sub-routes
      { source: '/artists/schedules', destination: '/artists?tab=schedules', permanent: false },
      { source: '/guest-artists', destination: '/artists?tab=guest-artists', permanent: false },
      { source: '/settings/team/permissions', destination: '/artists?tab=permissions', permanent: false },

      // Inventory sub-routes
      { source: '/settings/ink-registry', destination: '/inventory?tab=ink-registry', permanent: false },

      // Clients sub-routes
      { source: '/settings/tags', destination: '/clients?tab=tags', permanent: false },
      { source: '/consent-forms', destination: '/clients?tab=consent-forms', permanent: false },
      { source: '/ai-design', destination: '/clients?tab=ai-design', permanent: false },

      // S14 Settings Hub redirects — old flat URLs → new grouped /settings/{group}/{section}
      // All 307 (temporary) — upgrade to 308 after launch confirms stability.
      { source: '/settings/profile',      destination: '/settings/account/profile',      permanent: false },
      { source: '/settings/advanced',     destination: '/settings/account/advanced',     permanent: false },
      { source: '/settings/billing',      destination: '/settings/subscription/billing', permanent: false },
      { source: '/settings/services',     destination: '/settings/studio/services',      permanent: false },
      { source: '/settings/branding',     destination: '/settings/studio/branding',      permanent: false },
      { source: '/settings/booking-page', destination: '/settings/studio/booking-page',  permanent: false },
      { source: '/settings/policies',     destination: '/settings/studio/policies',      permanent: false },
      { source: '/settings/team',         destination: '/settings/team/members',         permanent: false },
      { source: '/settings/locations',    destination: '/locations',                     permanent: false },
      // NOTE: /settings/team/permissions — S13 already redirects to /artists?tab=permissions (S13 wins).
      // NOTE: /settings/ink-registry — S13 redirects to /inventory?tab=ink-registry.
      //   /settings/studio/ink-registry is accessible via sidebar nav directly.
      // NOTE: /settings root → handled by app/(app)/settings/page.tsx redirect().
    ]
  },

  async headers() {
    // Content-Security-Policy (QA #15 — OWASP A05)
    // Start strict; add per-vendor hashes in subsequent sprints.
    // 'unsafe-inline' is limited to styles to support Tailwind class injection.
    // Next.js 16 RSC inlines bootstrap/hydration scripts — requires 'unsafe-inline' on script-src.
    // 'unsafe-eval' is required for React dev-mode; keeps working in prod but can be dropped via nonce later.
    // Blob: scheme needed for workers (FullCalendar).
    const csp = [
      "default-src 'self'",
      "script-src 'self' 'unsafe-inline' 'unsafe-eval' blob:",
      "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
      "font-src 'self' data: https://fonts.gstatic.com",
      "img-src 'self' data: blob: https://*.supabase.co https://*.railway.app",
      "connect-src 'self' https://*.supabase.co wss://*.supabase.co https://app.posthog.com https://*.railway.app",
      "worker-src 'self' blob:",
      "frame-ancestors 'none'",
      "base-uri 'self'",
      "form-action 'self'",
      "object-src 'none'",
    ].join('; ')

    return [
      {
        source: '/:path*',
        headers: [
          {
            key: 'Strict-Transport-Security',
            value: 'max-age=63072000; includeSubDomains; preload',
          },
          { key: 'X-Frame-Options', value: 'DENY' },
          { key: 'X-Content-Type-Options', value: 'nosniff' },
          { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
          { key: 'Content-Security-Policy', value: csp },
          { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' },
        ],
      },
    ]
  },
  typescript: {
    ignoreBuildErrors: false,
  },
}

export default withBundleAnalyzer(nextConfig)

