'use client'

import { Link2 } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip'

interface HeaderBookingLinkButtonProps {
  studioSlug: string
  className?: string
}

/**
 * Top-bar utility — copy the studio's public booking URL to clipboard.
 * Icon-only to match the editorial-polish brand rule. Tooltip reveals the full URL.
 */
export function HeaderBookingLinkButton({
  studioSlug,
  className,
}: HeaderBookingLinkButtonProps) {
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'https://inkos.app'
  const bookingUrl = `${appUrl}/book/${studioSlug}`
  const displayUrl = bookingUrl.replace(/^https?:\/\//, '')

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(bookingUrl)
      toast.success('Booking link copied', {
        description: displayUrl,
      })
    } catch {
      toast.error('Could not copy link')
    }
  }

  return (
    <TooltipProvider delayDuration={300}>
      <Tooltip>
        <TooltipTrigger
          render={
            <button
              type="button"
              onClick={handleCopy}
              aria-label={`Copy booking link: ${displayUrl}`}
              className={cn(
                'flex h-8 w-8 shrink-0 cursor-pointer items-center justify-center rounded-lg',
                'text-muted-foreground/80 transition-colors duration-100',
                'hover:bg-muted/60 hover:text-foreground',
                'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
                className,
              )}
            />
          }
        >
          <Link2 className="h-4 w-4" aria-hidden="true" />
        </TooltipTrigger>
        <TooltipContent side="bottom" sideOffset={6} className="max-w-[260px]">
          <div className="flex flex-col gap-0.5">
            <span className="font-medium">Copy booking link</span>
            <span className="truncate text-[11px] text-muted-foreground/80">
              {displayUrl}
            </span>
          </div>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  )
}

