input.content:
'use client'

import { useState } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { toast } from 'sonner'
import { Crown, Shield, Palette, Phone, UserPlus, Loader2, Copy } from 'lucide-react'
import { cn } from '@/lib/utils'
import { usePermissions } from '@/lib/team/permissions-context'

// Generate a preview token (nanoid-style, 12 chars)
function generatePreviewToken(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'
  return Array.from({ length: 12 }, () => chars[Math.floor(Math.random() * chars.length)]).join('')
}

type Role = 'admin' | 'artist' | 'receptionist' | 'guest_artist' | 'owner'

const ROLES: {
  value: Role
  label: string
  description: string
  icon: React.ComponentType<{ className?: string }>
  ownerOnly?: boolean
}[] = [
  {
    value: 'owner',
    label: 'Owner',
    description: 'Full studio control. Billing, deletion, role management.',
    icon: Crown,
    ownerOnly: true,
  },
  {
    value: 'admin',
    label: 'Admin',
    description: 'Manage bookings, artists, clients. No billing or studio delete.',
    icon: Shield,
  },
  {
    value: 'artist',
    label: 'Artist',
    description: 'Manage own bookings, schedule, and clients.',
    icon: Palette,
  },
  {
    value: 'receptionist',
    label: 'Receptionist',
    description: 'Book and manage all appointments. No payroll access.',
    icon: Phone,
  },
  {
    value: 'guest_artist',
    label: 'Guest Artist',
    description: 'Limited access to own bookings and schedule only.',
    icon: UserPlus,
  },
]

interface InviteModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  defaultRole?: Role
  onSuccess?: () => void
}

export function InviteModal({ open, onOpenChange, defaultRole = 'artist', onSuccess }: InviteModalProps) {
  const { canDo } = usePermissions()
  const isOwner = canDo('admin.change_roles')

  const [email, setEmail] = useState('')
  const [role, setRole] = useState<Role>(defaultRole)
  const [commissionPct, setCommissionPct] = useState('30')
  const [personalMessage, setPersonalMessage] = useState('')
  const [emailError, setEmailError] = useState('')
  const [sending, setSending] = useState(false)
  // Preview token — generated once per modal open, replaced by real token after send
  const [previewToken] = useState(() => generatePreviewToken())
  const origin = typeof window !== 'undefined' ? window.location.origin : ''
  const previewUrl = `${origin}/invite/${previewToken}`

  const visibleRoles = ROLES.filter((r) => !r.ownerOnly || isOwner)

  const validateEmail = (value: string): boolean => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    if (!value.trim()) {
      setEmailError('Email is required')
      return false
    }
    if (!re.test(value.trim())) {
      setEmailError('Enter a valid email address')
      return false
    }
    setEmailError('')
    return true
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!validateEmail(email)) return

    setSending(true)
    try {
      const payload: Record<string, unknown> = {
        email: email.trim().toLowerCase(),
        role,
        personal_message: personalMessage.trim() || null,
      }
      if (role === 'artist') {
        payload.commission_pct = parseFloat(commissionPct) || 0
      }

      const res = await fetch('/api/team-invites', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      const json = await res.json() as { error?: string }

      if (!res.ok) {
        if (json.error === 'already_a_member') {
          toast.error('This person is already a member.')
        } else if (json.error === 'invalid_email') {
          setEmailError('This email address is not valid.')
        } else {
          toast.error(json.error ?? 'Failed to send invite')
        }
        return
      }

      toast.success(`Invite sent to ${email.trim()}`)
      setEmail('')
      setPersonalMessage('')
      setCommissionPct('30')
      setRole(defaultRole)
      onSuccess?.()
      onOpenChange(false)
    } catch {
      toast.error('Failed to send invite')
    } finally {
      setSending(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[720px] max-h-[calc(100vh-4rem)] overflow-y-auto p-0">
        <DialogHeader className="px-6 pt-6 pb-4 border-b border-border/60">
          <DialogTitle className="font-serif text-[26px] font-normal leading-tight tracking-tight">
            Invite a team member
          </DialogTitle>
          <p className="text-[13px] text-muted-foreground">
            Send an invitation by email. They&rsquo;ll accept through a secure link.
          </p>
        </DialogHeader>

        <form onSubmit={(e) => void handleSubmit(e)} className="flex flex-col">
          <div className="px-6 py-5 space-y-6">
            {/* ── WHO ─────────────────────────────────────────── */}
            <section className="space-y-4">
              <SectionHeader>Who</SectionHeader>

              <div className="space-y-1.5">
                <Label htmlFor="invite-email">
                  Email address <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="invite-email"
                  type="email"
                  placeholder="colleague@example.com"
                  value={email}
                  onChange={(e) => {
                    setEmail(e.target.value)
                    if (emailError) setEmailError('')
                  }}
                  onBlur={() => validateEmail(email)}
                  aria-invalid={!!emailError}
                  aria-describedby={emailError ? 'email-error' : undefined}
                />
                {emailError && (
                  <p id="email-error" role="alert" className="text-xs text-destructive">
                    {emailError}
                  </p>
                )}
              </div>

              <div className="space-y-2">
                <Label>
                  Role <span className="text-destructive">*</span>
                </Label>
                <RadioGroup
                  value={role}
                  onValueChange={(v) => setRole(v as Role)}
                  className="grid grid-cols-1 gap-2 sm:grid-cols-2"
                >
                  {visibleRoles.map((r, i) => {
                    const Icon = r.icon
                    const selected = role === r.value
                    const isLastOrphan =
                      i === visibleRoles.length - 1 &&
                      visibleRoles.length % 2 === 1
                    return (
                      <label
                        key={r.value}
                        className={cn(
                          'group flex min-h-[88px] cursor-pointer items-start gap-3 rounded-lg border p-3.5 transition-colors duration-150',
                          selected
                            ? 'border-destructive bg-destructive/[0.04]'
                            : 'border-border/60 hover:border-border hover:bg-muted/30',
                          isLastOrphan && 'sm:col-span-2',
                        )}
                      >
                        <RadioGroupItem value={r.value} className="mt-0.5" />
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <Icon
                              className={cn(
                                'h-4 w-4 shrink-0 transition-colors',
                                selected ? 'text-destructive' : 'text-muted-foreground',
                              )}
                            />
                            <p className="text-[14px] font-semibold leading-none">
                              {r.label}
                            </p>
                          </div>
                          <p className="mt-1.5 text-[12px] leading-snug text-muted-foreground">
                            {r.description}
                          </p>
                        </div>
                      </label>
                    )
                  })}
                </RadioGroup>
              </div>
            </section>

            {/* ── COMPENSATION (artist only) ─────────────────── */}
            {role === 'artist' && (
              <section className="space-y-4 border-t border-border/60 pt-5 animate-in fade-in-0 slide-in-from-top-1 duration-150">
                <SectionHeader>Compensation</SectionHeader>
                <div className="space-y-1.5">
                  <Label htmlFor="invite-commission" className="text-[13px]">
                    Commission %
                  </Label>
                  <div className="flex items-center gap-2">
                    <Input
                      id="invite-commission"
                      type="number"
                      min={0}
                      max={100}
                      className="w-24 tabular-nums"
                      value={commissionPct}
                      onChange={(e) => setCommissionPct(e.target.value)}
                    />
                    <span className="text-[13px] text-muted-foreground">%</span>
                  </div>
                  <p className="text-[11px] text-muted-foreground">
                    Studio keeps the remainder. Adjustable later in Team settings.
                  </p>
                </div>
              </section>
            )}

            {/* ── INVITATION ─────────────────────────────────── */}
            <section className="space-y-4 border-t border-border/60 pt-5">
              <SectionHeader>Invitation</SectionHeader>

              <div className="space-y-1.5">
                <Label className="text-[13px] text-muted-foreground">
                  Invite link preview
                </Label>
                <div className="flex items-center gap-2 rounded-lg border border-border/60 bg-muted/30 px-3 py-2">
                  <span className="min-w-0 flex-1 truncate font-mono text-[12px] text-muted-foreground">
                    {previewUrl}
                  </span>
                  <button
                    type="button"
                    onClick={() => {
                      void navigator.clipboard.writeText(previewUrl)
                      toast.success('Link copied')
                    }}
                    aria-label="Copy invite link"
                    className="flex h-6 w-6 shrink-0 cursor-pointer items-center justify-center rounded text-muted-foreground transition-colors hover:bg-muted/60 hover:text-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                  >
                    <Copy className="h-3.5 w-3.5" aria-hidden="true" />
                  </button>
                </div>
                <p className="text-[11px] text-muted-foreground">
                  This link activates after you send the invite.
                </p>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="invite-message" className="text-[13px]">
                  Personal message{' '}
                  <span className="text-[11px] text-muted-foreground">(optional)</span>
                </Label>
                <Textarea
                  id="invite-message"
                  rows={3}
                  placeholder="Looking forward to having you on the team!"
                  value={personalMessage}
                  onChange={(e) => setPersonalMessage(e.target.value)}
                />
              </div>
            </section>
          </div>

          {/* ── Sticky footer ─────────────────────────────────── */}
          <div className="sticky bottom-0 flex items-center justify-end gap-2 border-t border-border/60 bg-background px-6 py-4">
            <Button
              type="button"
              variant="ghost"
              onClick={() => onOpenChange(false)}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={sending}>
              {sending && (
                <Loader2
                  aria-hidden="true"
                  className="h-4 w-4 mr-2 animate-spin"
                />
              )}
              Send Invite →
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  )
}

function SectionHeader({ children }: { children: React.ReactNode }) {
  return (
    <h3 className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
      {children}
    </h3>
  )
}

